-- c003-v001: Na–nyoka alikuwa mjanja kuliko–wote wanyama–wa shamba–la ambao alifanya Bwana Mungu naye–akasema kwa mwanamke–wa je kweli alisema Mungu msile mtakula kutoka–kwa–kila mti–wa bustani–ya
-- c003-v002: Naye–akasema mwanamke–wa kwa nyoka–wa kutoka–matunda–ya mti–wa bustani–ya tunaweza–kula
-- c003-v003: Lakini–kutoka–matunda–ya mti–wa ambao katikati–ya bustani–ya alisema Mungu msile mtakula kutoka–kwake na–msiguse mtaugusa huo msije mkafa
-- c003-v004: Naye–akasema nyoka–wa kwa mwanamke–wa hamtakufa kufa mtakufa
-- c003-v005: Kwa–sababu anajua Mungu kwamba katika–siku kula–kwenu kutoka–kwake na–zitafunguliwa macho–yenu na–mtakuwa kama–Mungu mkijua mema na–mabaya
-- c003-v006: Naye–akaona mwanamke–wa kwamba mzuri mti–wa kwa–chakula na–kwamba wa–kutamaniwa huo kwa–macho na–wa–kupendeza mti–wa kufanya–wenye–hekima naye–akachukua kutoka–matunda–yake naye–akala naye–akampa pia mume–wake pamoja–naye naye–akala
-- c003-v007: Na–yakafunguliwa macho–ya wote–wawili nao–wakajua kwamba uchi wao nao–wakashona majani–ya mtini nao–wakajifanyia wao nguo–za–kujifunika
-- c003-v008: Nao–wakasikia – sauti–ya Bwana Mungu akitembea katika–bustani wakati–wa–upepo wa–mchana naye–akajificha mtu–wa na–mke–wake kutoka–uso–wa Bwana Mungu katikati–ya miti–ya bustani–ya
-- c003-v009: Naye–akaita Bwana Mungu kwa mtu–wa naye–akamwambia yeye uko–wapi
-- c003-v010: Naye–akasema – sauti–yako nilisikia katika–bustani na–nikaogopa kwa–sababu uchi mimi na–nikajificha
-- c003-v011: Naye–akasema nani alikuambia wewe kwamba uchi wewe je–kutoka–kwa mti–wa ambao nilikuamuru kutokula kula kutoka–kwake umekula
-- c003-v012: Naye–akasema mtu–wa mwanamke–wa ambaye ulinipa pamoja–nami yeye alinipa mimi kutoka–kwa mti–wa na–nikala
-- c003-v013: Naye–akasema Bwana Mungu kwa–mwanamke nini hiki umefanya naye–akasema mwanamke–wa nyoka–wa alinidanganya na–nikala
-- c003-v014: Naye–akasema Bwana Mungu kwa nyoka–wa kwa–sababu umefanya hivi umelaaniwa wewe kuliko–wote wanyama–wa na–kuliko–wote wanyama–wa shamba–la juu–ya tumbo–lako utakwenda na–mavumbi utakula kila siku–za maisha–yako
-- c003-v015: Na–uadui nitaweka kati–yako na–kati–ya mwanamke–wa na–kati–ya uzao–wako na–kati–ya uzao–wake yeye atakuponda kichwa na–wewe utamponda kisigino ¶
-- c003-v016: Kwa mwanamke–wa akasema kuzidisha nitazidisha maumivu–yako na–mimba–yako kwa–maumivu utazaa watoto na–kwa mume–wako shauku–yako na–yeye atakutawala wewe ¶
-- c003-v017: Na–kwa–Adamu akasema kwa–sababu ulisikiliza sauti–ya mke–wako na–ukala kutoka–kwa mti–wa ambao nilikuamuru akisema usile utakula kutoka–kwake imelaaniwa ardhi–ya kwa–sababu–yako kwa–maumivu utaila kila siku–za maisha–yako
-- c003-v018: Na–miiba na–michongoma itachipusha kwako na–utakula – mimea–ya shamba–la
-- c003-v019: Kwa–jasho uso–wako utakula mkate hadi kurudi–kwako kwenye ardhi–ya kwa–sababu kutoka–kwake ulichukuliwa kwa–sababu mavumbi wewe na–kwenye mavumbi utarudi
-- c003-v020: Naye–akamwita mtu–wa jina–la mke–wake Hawa kwa–sababu yeye alikuwa mama–wa kila aliye–hai
-- c003-v021: Naye–akafanya Bwana Mungu kwa–Adamu na–kwa–mke–wake nguo–za ngozi naye–akawavisha ¶
-- c003-v022: Naye–akasema Bwana Mungu tazama mtu–wa amekuwa kama–mmoja wetu kujua mema na–mabaya na–sasa asije akanyoosha mkono–wake na–akachukua pia kutoka–mti–wa uhai–wa na–akala na–akaishi milele
-- c003-v023: Naye–akamtoa Bwana Mungu kutoka–bustani–ya Edeni kulima – ardhi–ya ambayo alichukuliwa kutoka–huko
-- c003-v024: Naye–akamfukuza – mtu–wa naye–akaweka mashariki wa–bustani–ya Edeni – makerubi–wa na– mwali–wa upanga–wa unaozunguka kulinda – njia–ya mti–wa uhai–wa ¶

